ALTER TABLE `UserData` ADD `masteryRanks` json DEFAULT ('{}') NOT NULL;







-- Preserve earned mastery. Existing totals above the cap cannot gain further points.
UPDATE `UserData` SET `masteryRanks` = JSON_OBJECT('ninjutsuMastery', CASE WHEN `ninjutsuMastery` >= 1500000 THEN 'LEGENDARY' WHEN `ninjutsuMastery` > 1000000 THEN 'MASTER' WHEN `ninjutsuMastery` > 600000 THEN 'ADEPT' WHEN `ninjutsuMastery` > 375000 THEN 'NOVICE' ELSE 'NONE' END, 'genjutsuMastery', CASE WHEN `genjutsuMastery` >= 1500000 THEN 'LEGENDARY' WHEN `genjutsuMastery` > 1000000 THEN 'MASTER' WHEN `genjutsuMastery` > 600000 THEN 'ADEPT' WHEN `genjutsuMastery` > 375000 THEN 'NOVICE' ELSE 'NONE' END, 'taijutsuMastery', CASE WHEN `taijutsuMastery` >= 1500000 THEN 'LEGENDARY' WHEN `taijutsuMastery` > 1000000 THEN 'MASTER' WHEN `taijutsuMastery` > 600000 THEN 'ADEPT' WHEN `taijutsuMastery` > 375000 THEN 'NOVICE' ELSE 'NONE' END, 'bukijutsuMastery', CASE WHEN `bukijutsuMastery` >= 1500000 THEN 'LEGENDARY' WHEN `bukijutsuMastery` > 1000000 THEN 'MASTER' WHEN `bukijutsuMastery` > 600000 THEN 'ADEPT' WHEN `bukijutsuMastery` > 375000 THEN 'NOVICE' ELSE 'NONE' END, 'bloodlineMastery', CASE WHEN `bloodlineMastery` >= 1500000 THEN 'LEGENDARY' WHEN `bloodlineMastery` > 1000000 THEN 'MASTER' WHEN `bloodlineMastery` > 600000 THEN 'ADEPT' WHEN `bloodlineMastery` > 375000 THEN 'NOVICE' ELSE 'NONE' END, 'sageMastery', CASE WHEN `sageMastery` >= 1500000 THEN 'LEGENDARY' WHEN `sageMastery` > 1000000 THEN 'MASTER' WHEN `sageMastery` > 600000 THEN 'ADEPT' WHEN `sageMastery` > 375000 THEN 'NOVICE' ELSE 'NONE' END);

